mapper.select:
SELECT 
FROM rule_workbook_versions v
JOIN rule_workbooks w ON w.id = v.workbook_id
WHERE v.workbook_id = #{workbookId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND w.owner_id = #{ownerId}
ORDER BY v.version_number DESC

SELECT 
FROM rule_workbook_versions v
JOIN rule_workbooks w ON w.id = v.workbook_id
WHERE v.id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND w.owner_id = #{ownerId}

SELECT 
FROM rule_workbook_versions v
JOIN rule_workbooks w ON w.id = v.workbook_id
WHERE v.workbook_id = #{workbookId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND v.version_number = #{versionNumber}
  AND w.owner_id = #{ownerId}

SELECT COALESCE(MAX(version_number), 0)
FROM rule_workbook_versions
WHERE workbook_id = #{workbookId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
